 "<b style=\"font-size:24px;color:#7a8f6b\">Calzado</b><br><span style=\"font-size:20px;color:#2a2a26\">3 pares versátiles.</span>": "<b style=\"font-size:24px;color:#7a8f6b\">الأحذية</b><br><span style=\"font-size:20px;color:#2a2a26\">3 أزواج متعددة الاستخدام.</span>",
 "<b style=\"font-size:24px;color:#b5651d\">Un vestido o traje</b><br><span style=\"font-size:20px;color:#2a2a26\">2 para ocasiones especiales.</span>": "<b style=\"font-size:24px;color:#b5651d\">فستان أو بدلة</b><br><span style=\"font-size:20px;color:#2a2a26\">2 للمناسبات الخاصة.</span>",
