 "Cuántas combinaciones salen": "كم تنسيقًا ينتج",
 "8 + 5 + 4 capas": "8 + 5 + 4 طبقات",
 "Conjuntos posibles": "الأطقم الممكنة",
 "Combinaciones": "التنسيقات",
 "<b style=\"font-size:25px;color:#7a8f6b\">Cálculo</b><br><span style=\"font-size:20px;color:#2a2a26\">Cada parte de arriba con cada de abajo: 8 por 5 son 40 conjuntos.</span>": "<b style=\"font-size:25px;color:#7a8f6b\">الحساب</b><br><span style=\"font-size:20px;color:#2a2a26\">كل قطعة علوية مع كل قطعة سفلية: 8 في 5 يساوي 40 طقمًا.</span>",
